/**
 * קרוסלה (REDESIGN-PLAN §7) — גלילה אופקית מקורית + scroll-snap; המודול מוסיף:
 * גרירת עכבר עם אינרציה, חיצים במקלדת לפי הכיוון *החזותי*, כפתורי הקודם/הבא, הכרזת "3 מתוך 8",
 * ועומק: כל כרטיס מקבל --d (מרחק מהמרכז ביחידות כרטיס) ו---ad (ערך מוחלט) ל-CSS.
 * עובד זהה ב-RTL וב-LTR: כל החישובים מתבססים על מלבני מסך (getBoundingClientRect), לא על scrollLeft.
 *
 * מבנה:
 *  [data-carousel] > [data-car-track] > [data-car-slide]*
 *  [data-car-prev] [data-car-next] [data-car-status] (אופציונליים, בתוך [data-carousel])
 */
const reducedMotion = () =>
  matchMedia('(prefers-reduced-motion: reduce)').matches || document.documentElement.dataset.motion === 'reduced';

export function initCarousel(root: HTMLElement) {
  const track = root.querySelector<HTMLElement>('[data-car-track]');
  if (!track) return;
  const slides = () => Array.from(track.querySelectorAll<HTMLElement>('[data-car-slide]')).filter((s) => !s.hidden);
  const prev = root.querySelector<HTMLButtonElement>('[data-car-prev]');
  const next = root.querySelector<HTMLButtonElement>('[data-car-next]');
  const status = root.querySelector<HTMLElement>('[data-car-status]');
  const rtl = () => getComputedStyle(track).direction === 'rtl';
  const tpl = status?.dataset.tpl ?? '{i} / {n}';

  const center = (el: Element) => { const r = el.getBoundingClientRect(); return r.left + r.width / 2; };
  const current = () => {
    const tc = center(track); let best = 0, bd = Infinity;
    slides().forEach((s, i) => { const d = Math.abs(center(s) - tc); if (d < bd) { bd = d; best = i; } });
    return best;
  };

  /* ---------- עומק ---------- */
  let depthRaf = 0;
  const depth = () => {
    depthRaf = 0;
    const tc = center(track);
    for (const s of slides()) {
      const r = s.getBoundingClientRect();
      const d = Math.max(-3, Math.min(3, (r.left + r.width / 2 - tc) / (r.width || 1)));
      s.style.setProperty('--d', d.toFixed(3));
      s.style.setProperty('--ad', Math.abs(d).toFixed(3));
      s.classList.toggle('is-active', Math.abs(d) < 0.5);
    }
    syncButtons();
  };
  const queueDepth = () => { if (!depthRaf) depthRaf = requestAnimationFrame(depth); };

  const syncButtons = () => {
    const i = current(), n = slides().length;
    if (prev) prev.disabled = i <= 0;
    if (next) next.disabled = i >= n - 1;
  };
  const announce = () => {
    if (!status) return;
    status.textContent = tpl.replace('{i}', String(current() + 1)).replace('{n}', String(slides().length));
  };

  const goTo = (i: number, speak = false) => {
    const list = slides();
    const s = list[Math.max(0, Math.min(list.length - 1, i))];
    if (!s) return;
    track.scrollBy({ left: center(s) - center(track), behavior: reducedMotion() ? 'auto' : 'smooth' });
    if (speak) setTimeout(announce, reducedMotion() ? 0 : 420);
  };

  prev?.addEventListener('click', () => goTo(current() - 1, true));
  next?.addEventListener('click', () => goTo(current() + 1, true));

  /* ---------- מקלדת: חץ לפי הכיוון החזותי (ב-RTL ← = הבא) ---------- */
  track.addEventListener('keydown', (e) => {
    const k = e.key;
    if (k !== 'ArrowLeft' && k !== 'ArrowRight' && k !== 'Home' && k !== 'End') return;
    e.preventDefault();
    if (k === 'Home') return goTo(0, true);
    if (k === 'End') return goTo(slides().length - 1, true);
    const visualRight = k === 'ArrowRight';
    const step = (visualRight !== rtl()) ? 1 : -1; // LTR: ימינה = הבא; RTL: שמאלה = הבא
    goTo(current() + step, true);
  });
  // פוקוס על כרטיס (Tab) → הכרטיס עובר למרכז
  track.addEventListener('focusin', (e) => {
    const s = (e.target as HTMLElement).closest<HTMLElement>('[data-car-slide]');
    if (s && Math.abs(center(s) - center(track)) > 4) goTo(slides().indexOf(s));
  });

  /* ---------- גרירת עכבר עם אינרציה ---------- */
  // הגרירה מתחילה רק אחרי תזוזה של 6px: לחיצה רגילה על כרטיס נשארת לחיצה (pointer capture מוקדם "גנב" את
  // הלחיצה מהקישור — באג שנמצא בבדיקת המעבר כרטיס→עמוד, 2026-09-26)
  let pressed = false, dragging = false, moved = 0, lastX = 0, lastT = 0, vel = 0, inertia = 0, pid = 0;
  track.addEventListener('pointerdown', (e) => {
    if (e.pointerType !== 'mouse' || e.button !== 0) return;
    cancelAnimationFrame(inertia);
    pressed = true; dragging = false; moved = 0; lastX = e.clientX; lastT = performance.now(); vel = 0; pid = e.pointerId;
  });
  track.addEventListener('pointermove', (e) => {
    if (!pressed) return;
    if (!dragging) {
      if (Math.abs(e.clientX - lastX) < 6) return;
      dragging = true; track.setPointerCapture(pid); root.classList.add('is-dragging');
    }
    const now = performance.now(), dx = e.clientX - lastX;
    track.scrollLeft -= dx;
    moved += Math.abs(dx);
    const dt = Math.max(1, now - lastT);
    vel = 0.8 * (dx / dt) + 0.2 * vel; // px/ms, מוחלק
    lastX = e.clientX; lastT = now;
  });
  const endDrag = () => {
    pressed = false;
    if (!dragging) return;
    dragging = false;
    let v = vel * 16; // px/frame
    const glide = () => {
      if (Math.abs(v) < 0.6 || reducedMotion()) { root.classList.remove('is-dragging'); goTo(current()); return; }
      track.scrollLeft -= v; v *= 0.92;
      inertia = requestAnimationFrame(glide);
    };
    inertia = requestAnimationFrame(glide);
  };
  track.addEventListener('pointerup', endDrag);
  track.addEventListener('pointercancel', endDrag);
  // לחיצה אחרי גרירה אינה ניווט
  track.addEventListener('click', (e) => { if (moved > 6) { e.preventDefault(); e.stopPropagation(); moved = 0; } }, true);
  track.addEventListener('dragstart', (e) => e.preventDefault());

  track.addEventListener('scroll', queueDepth, { passive: true });
  addEventListener('resize', queueDepth, { passive: true });
  depth();
  return { goTo, refresh: depth };
}

export function initCarousels(root: ParentNode = document) {
  return Array.from(root.querySelectorAll<HTMLElement>('[data-carousel]')).map((el) => initCarousel(el));
}
